<script setup lang="ts">
import { onMounted, ref, watch } from 'vue';
import { api, errorMessage } from '../services/api';
import { useAuth } from '../stores/auth';
import StateNotice from '../components/StateNotice.vue';
import MatchCard from '../components/MatchCard.vue';
const tab = ref('competitions'), q = ref(''), items = ref<any[]>([]), seasons = ref<any[]>([]), seasonId = ref(''), position = ref(''), standings = ref<any[]>([]), sources = ref<any>(), selectedTeam = ref<any>();
const busy = ref(false), error = ref(''), message = ref(''), competition = ref('PL'), year = ref(new Date().getFullYear()), auth = useAuth();
async function load() { busy.value = true; error.value = ''; selectedTeam.value = undefined; try {
  if (tab.value === 'standings') { standings.value = seasonId.value ? (await api.get('/statistics/standings', { params: { seasonId: seasonId.value } })).data.items : []; items.value = []; }
  else if (tab.value === 'favorites') items.value = (await api.get('/favorites')).data;
  else items.value = (await api.get(`/${tab.value}`, { params: { q: q.value, ...(seasonId.value && ['players', 'matches'].includes(tab.value) ? { seasonId: seasonId.value } : {}), ...(position.value && tab.value === 'players' ? { position: position.value } : {}) } })).data.items;
} catch (e) { error.value = errorMessage(e); } finally { busy.value = false; } }
async function sync() { busy.value = true; error.value = ''; try { const { data } = await api.post('/integrations/football-data/sync', { competition: competition.value, season: year.value }, { timeout: 150000 }); message.value = `${data.matches} partidos importados. ${data.statistics}`; seasons.value = (await api.get('/competitions/seasons')).data; await load(); } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; } }
async function importStatsBomb(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; busy.value = true; error.value = ''; try { const raw = await file.text(); const payload = JSON.parse(raw); if (new window.TextEncoder().encode(JSON.stringify(payload)).byteLength > 4 * 1024 * 1024) throw new Error('El paquete supera 4 MB. Importa un paquete más pequeño.'); const { data } = await api.post('/integrations/statsbomb/import', payload, { timeout: 150000 }); message.value = `Importados ${data.playersWithMinutes} jugadores con minutos. ${data.attribution}`; await load(); } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; } }
async function team(id: string) { try { selectedTeam.value = (await api.get(`/teams/${id}`)).data; } catch (e) { error.value = errorMessage(e); } }
async function favorite(b: any) { try { await api.post('/favorites', b); message.value = 'Guardado en favoritos'; } catch (e) { error.value = errorMessage(e); } }
async function removeFavorite(id: string) { try { await api.delete(`/favorites/${id}`); await load(); } catch (e) { error.value = errorMessage(e); } }
onMounted(async () => { try { [seasons.value, sources.value] = await Promise.all([api.get('/competitions/seasons').then(r => r.data), api.get('/integrations').then(r => r.data)]); } catch (e) { error.value = errorMessage(e); } await load(); });
watch([tab, seasonId, position], load);
</script>
<template><section><div class="page-heading"><div><span class="eyebrow">FOOTLAB PRO</span><h1>Todo un mundo <span class="accent">de fútbol.</span></h1><p>Competiciones, equipos y futbolistas. Datos con procedencia.</p></div><span class="pill">FÚTBOL PROFESIONAL</span></div><div class="tabs"><button v-for="t in [['competitions', 'Competiciones'], ['teams', 'Equipos'], ['players', 'Jugadores'], ['matches', 'Partidos'], ['standings', 'Clasificación'], ['favorites', 'Favoritos']]" :key="t[0]" :class="{ active: tab === t[0] }" @click="tab = t[0]!">{{ t[1] }}</button></div><form class="filter-bar" @submit.prevent="load"><label class="search"><i aria-hidden="true" class="pi pi-search" /><input v-model="q" placeholder="Buscar en el fútbol profesional" aria-label="Buscar"></label><select v-model="seasonId" aria-label="Temporada"><option value="">{{ tab === 'standings' ? 'Selecciona una temporada' : 'Todas las temporadas' }}</option><option v-for="s in seasons" :key="s.id" :value="s.id">{{ s.competition.name }} · {{ s.name }}</option></select><select v-if="tab === 'players'" v-model="position" aria-label="Posición"><option value="">Todas las posiciones</option><option v-for="p in ['GK', 'DF', 'MF', 'FW']" :key="p">{{ p }}</option></select><button class="button subtle">Buscar</button></form><p v-if="message" class="alert success" role="status">{{ message }}</p><StateNotice :loading="busy" :error="error" :empty="!busy && !error && !items.length && !standings.length" @retry="load" /><template v-if="!busy && !error"><div v-if="tab === 'players'" class="player-grid"><article v-for="p in items" :key="p.id" class="player-card"><div class="player-card-top"><span class="position">{{ p.position }}</span><button class="icon-button" aria-label="Guardar favorito" @click="favorite({ playerId: p.id })"><i aria-hidden="true" class="pi pi-star" /></button></div><div class="player-avatar">{{ p.name.split(' ').map((n: string) => n[0]).slice(0, 2).join('') }}</div><RouterLink :to="`/players/${p.id}`"><h3>{{ p.name }}</h3></RouterLink><p>{{ p.nationality ?? 'Nacionalidad no disponible' }}</p><span class="source-tag">{{ p.source }}</span></article></div><div v-else-if="tab === 'matches'" class="match-list"><MatchCard v-for="m in items" :key="m.id" :match="m" /></div><div v-else-if="tab === 'standings' && standings.length" class="panel table-scroll"><table><thead><tr><th>#</th><th>Equipo</th><th>PJ</th><th>G</th><th>E</th><th>P</th><th>DG</th><th>PTS</th></tr></thead><tbody><tr v-for="(s, i) in standings" :key="s.id"><td>{{ i + 1 }}</td><td>{{ s.name }}</td><td>{{ s.played }}</td><td>{{ s.won }}</td><td>{{ s.drawn }}</td><td>{{ s.lost }}</td><td>{{ s.gd }}</td><td class="accent">{{ s.points }}</td></tr></tbody></table><p class="chart-footnote">Calculada con resultados disponibles; sin deducciones disciplinarias.</p></div><div v-else class="list-grid"><article v-for="item in items" :key="item.id" class="panel list-item"><i aria-hidden="true" :class="['pi', tab === 'teams' ? 'pi-shield' : 'pi-trophy', 'list-icon']" /><div><h3>{{ item.name ?? item.player?.name ?? item.team?.name }}</h3><p>{{ item.country ?? item.category ?? item.player?.position ?? 'Favorito' }}</p><span v-if="item.source" class="source-tag">{{ item.source }}</span></div><button v-if="tab === 'teams'" class="icon-button" aria-label="Ver equipo" @click="team(item.id)"><i aria-hidden="true" class="pi pi-arrow-up-right" /></button><button v-if="tab === 'teams'" class="icon-button" aria-label="Añadir equipo a favoritos" @click="favorite({ teamId: item.id })"><i aria-hidden="true" class="pi pi-star" /></button><button v-if="tab === 'competitions'" class="button subtle" @click="seasonId = seasons.find(s => s.competitionId === item.id)?.id ?? ''; tab = 'standings'">Clasificación</button><RouterLink v-if="tab === 'favorites' && item.player" class="text-link" :to="{ path: `/players/${item.playerId}`, query: item.player.organizationId ? { organizationId: item.player.organizationId } : {} }">Ver perfil</RouterLink><button v-if="tab === 'favorites'" class="icon-button" aria-label="Eliminar favorito" @click="removeFavorite(item.id)"><i aria-hidden="true" class="pi pi-times" /></button></article></div><section v-if="selectedTeam" class="panel section-gap"><h2>{{ selectedTeam.name }}</h2><p class="muted">Historial de plantilla disponible</p><RouterLink v-for="p in selectedTeam.squads" :key="p.id" class="roster-row" :to="`/players/${p.playerId}`">{{ p.player.name }} <span>{{ p.season.name }} · {{ p.player.position }}</span></RouterLink></section></template><section class="panel section-gap"><span class="eyebrow">PROCEDENCIA DE LOS DATOS</span><p>football-data.org · StatsBomb Open Data. El catálogo aparece después de importar datos. La cobertura depende del proveedor y del plan contratado.</p><div v-if="auth.user?.globalRole === 'ADMIN'" class="section-gap"><h3>Importaciones</h3><form class="inline-form" @submit.prevent="sync"><input v-model="competition" aria-label="Código de competición" placeholder="PL"><input v-model.number="year" aria-label="Año de temporada" type="number"><button class="button primary" :disabled="busy">Sincronizar football-data.org</button></form><p class="muted">Token del proveedor: {{ sources?.footballData.configured ? 'configurado' : 'pendiente en el backend' }}</p><label class="file-input">Importar paquete JSON de StatsBomb <input type="file" accept="application/json,.json" @change="importStatsBomb"></label></div></section></section></template>
